#define main archived_ising_main
#include "../ising-cuda/main.cu"
#undef main
#include <vector>
#include <algorithm>
#define CK(c) do{cudaError_t e=(c);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{long long nx,ny;int sweeps;float beta;std::vector<float>u;std::vector<signed char>gold[3];signed char*b,*w;float*du;};
std::vector<signed char> physical(Case&c,int steps){int nx=c.nx,ny=c.ny,h=ny/2;std::vector<signed char>g(nx*ny);for(int i=0;i<nx;i++)for(int j=0;j<ny;j++)g[i*ny+j]=c.u[i*h+j/2]<.5f?-1:1;
 for(int step=0;step<steps;step++)for(int color=0;color<2;color++)for(int i=0;i<nx;i++)for(int j=0;j<ny;j++)if((i+j)%2==color){int spin=g[i*ny+j],nn=g[((i+nx-1)%nx)*ny+j]+g[((i+1)%nx)*ny+j]+g[i*ny+(j+ny-1)%ny]+g[i*ny+(j+1)%ny];if(double(c.u[i*h+j/2])<exp(-double(c.beta)*(2*spin*nn)))g[i*ny+j]=-spin;}
 std::vector<signed char>v;for(int color=0;color<2;color++)for(int i=0;i<nx;i++)for(int j=0;j<h;j++)v.push_back(g[i*ny+2*j+(color==0?i%2:1-i%2)]);return v;}
void launch(Case&c,int kind){int blocks=(c.nx*c.ny/2+127)/128;if(kind<2)init_spins<<<blocks,128>>>(kind==0?c.b:c.w,c.du,c.nx,c.ny/2);else if(kind==2)update_lattice<true><<<blocks,128>>>(c.b,c.w,c.du,c.beta,c.nx,c.ny/2);else update_lattice<false><<<blocks,128>>>(c.w,c.b,c.du,c.beta,c.nx,c.ny/2);}
void capture(Case&c,std::vector<float>&v){int n=c.nx*c.ny/2;std::vector<signed char>tmp(2*n);CK(cudaMemcpy(tmp.data(),c.b,n,cudaMemcpyDeviceToHost));CK(cudaMemcpy(tmp.data()+n,c.w,n,cudaMemcpyDeviceToHost));for(auto x:tmp)v.push_back(float(x));}
int main(){std::vector<Case>cs;std::vector<float>prefix;int dims[3][3]={{18,34,17},{32,66,18},{2,4,19}};float alphas[3]={.5f,1.f,2.f};for(int k=0;k<3;k++){Case c;c.nx=dims[k][0];c.ny=dims[k][1];c.sweeps=dims[k][2];c.beta=1.f/(alphas[k]*TCRIT);int n=c.nx*c.ny/2;for(int i=0;i<n;i++)c.u.push_back(float(((37*i+11)%65536)+.5)/65536.f);c.u[0]=0;c.u[1]=.5f;c.u[2]=1;for(float x:{float(c.nx),float(c.ny),float(c.sweeps),alphas[k],c.beta})prefix.push_back(x);prefix.insert(prefix.end(),c.u.begin(),c.u.end());
 CK(cudaMalloc(&c.b,n));CK(cudaMalloc(&c.w,n));CK(cudaMalloc(&c.du,n*4));CK(cudaMemcpy(c.du,c.u.data(),n*4,cudaMemcpyHostToDevice));for(int kind=0;kind<4;kind++)launch(c,kind);
 int steps[3]={0,2,c.sweeps+2};for(int phase=0;phase<3;phase++){c.gold[phase]=physical(c,steps[phase]);std::vector<signed char>b(n),w(n);init_spins_ref(b.data(),c.u.data(),c.nx,c.ny/2);init_spins_ref(w.data(),c.u.data(),c.nx,c.ny/2);for(int it=0;it<steps[phase];it++)update_ref(b.data(),w.data(),c.u.data(),c.beta,c.nx,c.ny);b.insert(b.end(),w.begin(),w.end());if(b!=c.gold[phase]){puts("Source CPU vs physical oracle fail");return 3;}}
 cs.push_back(c);}CK(cudaDeviceSynchronize());bool all=true;
 for(int trial=1;trial<=5;trial++){std::vector<std::vector<float>>captured(3);for(int k=0;k<3;k++){auto&c=cs[k];launch(c,0);launch(c,1);CK(cudaDeviceSynchronize());capture(c,captured[k]);for(int it=0;it<2;it++){launch(c,2);launch(c,3);}CK(cudaDeviceSynchronize());capture(c,captured[k]);}
 CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(auto&c:cs)for(int it=0;it<c.sweeps;it++){launch(c,2);launch(c,3);}CK(cudaGetLastError());CK(cudaDeviceSynchronize());double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/54;bool ok=true;auto out=prefix;std::vector<float>observables;
 for(int k=0;k<3;k++){auto&c=cs[k];capture(c,captured[k]);size_t pos=0;for(int phase=0;phase<3;phase++)for(auto x:c.gold[phase])ok=ok&&(captured[k][pos++]==float(x));out.insert(out.end(),captured[k].begin(),captured[k].end());auto&v=c.gold[2];int nx=c.nx,ny=c.ny,h=ny/2,n=nx*h,mag=0,energy=0;auto at=[&](int i,int j){int color=(i+j)%2;return int(v[color*n+i*h+j/2]);};for(int i=0;i<nx;i++)for(int j=0;j<ny;j++){mag+=at(i,j);energy-=at(i,j)*(at((i+1)%nx,j)+at(i,(j+1)%ny));}observables.push_back(mag);observables.push_back(energy);}
 out.insert(out.end(),observables.begin(),observables.end());all&=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");if(!f)return 4;fwrite(out.data(),4,out.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":8196,\"max_abs_error\":%d,\"max_rel_error\":0,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":54,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,sec,ok?"true":"false",ok?0:2,path.c_str(),out.size());}
 puts(all?"PASS":"FAIL");return all?0:1;}
